function summary(s){return {complete:s.complete,hp:s.hp,gold:s.gold,potions:s.potions,items:s.items,damage:attackRange(s),achievements:s.achievements,npcs:Object.fromEntries(PEOPLE.map(id=>[id,s.npcs[id]]))};}
function helpful(){let s=fresh();act(s,'chest','Open');act(s,'note','Read');for(const id of ['tobin','mara']){act(s,id,'Talk');act(s,id,'Help');act(s,id,'Befriend');act(s,id,'Trade');s=checkpoint(s);}act(s,'crate','Break');act(s,'rat','Offer cheese');act(s,'pipe','Search');act(s,'vex','Talk');act(s,'vex','Help');act(s,'vex','Befriend');act(s,'vex','Trade');useWhetstone(s);s=finish(s);for(const id of PEOPLE){assert.equal(s.npcs[id].attitude,'friendly');assert.equal(s.npcs[id].condition,'conscious');}assert.deepEqual(attackRange(s),[7,9]);return s;}
function thief(){let s=fresh();const vexAway=relocate(s,'vex',3,2,2),vexRoutine=NPCS.vex.routine;NPCS.vex.routine='guard';act(s,'chest','Open');act(s,'note','Read');act(s,'tobin','Talk');act(s,'tobin','Lie');act(s,'tobin','Trade');act(s,'tobin','Pickpocket');act(s,'mara','Talk');act(s,'mara','Help');act(s,'mara','Befriend');act(s,'mara','Lie');act(s,'mara','Pickpocket');NPCS.vex.routine=vexRoutine;vexAway();s=checkpoint(s);act(s,'vex','Talk');assert(!s.npcs.vex.memory.sawTheft,'Vex was in another room and cannot know about the thefts');assert(!s.npcs.vex.memory.sawRob);act(s,'vex','Lie');act(s,'vex','Pickpocket');travel(s,3);travel(s,4);useWhetstone(s);s=finish(s);for(const id of PEOPLE){assert.equal(s.npcs[id].attitude,'hostile');assert.equal(s.npcs[id].condition,'conscious');assert(s.npcs[id].memory.theftDetected);}assert(s.npcs.mara.memory.betrayed);return s;}
function violent(){let s=fresh();const vexAway=relocate(s,'vex',3,2,2),vexRoutine=NPCS.vex.routine;NPCS.vex.routine='guard';act(s,'chest','Open');act(s,'tobin','Rob openly');act(s,'tobin','Knock unconscious');win(s);act(s,'tobin','Loot');act(s,'tobin','Kill');s=checkpoint(s);for(const id of ['mara','vex']){act(s,'fountain','Heal');act(s,id,'Attack');win(s);act(s,id,'Loot');s=checkpoint(s);}useWhetstone(s);s=finish(s);for(const id of PEOPLE){assert.equal(s.npcs[id].condition,'dead');assert(s.npcs[id].memory.killed);assert(STOCK_KEYS.every(k=>s.npcs[id].inventory[k]===0));}assert(!s.npcs.vex.memory.sawKill,'Vex was elsewhere and did not see Tobin die');NPCS.vex.routine=vexRoutine;vexAway();return s;}
const report={};
